def run_agent(client, tools, prompt, max_turns=5):
    messages = [{"role": "user", "content": prompt}]
    for _ in range(max_turns):
        reply = client.create(messages)
        if reply["type"] == "text":
            return reply["text"]
        fn = tools.get(reply["name"])
